require 'thread'
require 'json'
require 'securerandom'
require 'fileutils'

module SafeSerializer
  class AuditLog
    AUDIT_DIR = '/var/log/serializer'

    def initialize
      @mutex = Mutex.new
      @pending_entries = []
      @flush_thread = start_flush_thread
    end

    def log_operation(operation, object_id, metadata = {})
      entry = {
        timestamp: Time.now.utc.iso8601(6),
        operation: operation,
        object_id: object_id,
        thread_id: Thread.current.object_id,
        metadata: metadata
      }
      @mutex.synchronize { @pending_entries << entry }
    end

    def flush!
      entries = @mutex.synchronize do
        batch = @pending_entries.dup
        @pending_entries.clear
        batch
      end
      write_entries(entries) unless entries.empty?
    end

    private

    def start_flush_thread
      Thread.new do
        loop do
          sleep 0.1
          flush!
        end
      end
    end

    def write_entries(entries)
      path = File.join(AUDIT_DIR, "audit_#{Date.today.iso8601}.jsonl")
      File.open(path, 'a') do |f|
        entries.each { |e| f.puts(JSON.generate(e)) }
      end
    end
  end

  class SerializationContext
    attr_reader :id, :state, :permissions

    def initialize(permissions: [])
      @id = SecureRandom.uuid
      @state = :initialized
      @permissions = permissions.freeze
      @serialized_data = nil
      @deserialized_object = nil
      @state_lock = Mutex.new
      @data_lock = Mutex.new
    end

    def transition_to(new_state)
      @state_lock.synchronize { @state = new_state }
    end

    def set_serialized_data(data)
      @data_lock.synchronize { @serialized_data = data }
    end

    def get_serialized_data
      @data_lock.synchronize { @serialized_data }
    end

    def set_deserialized_object(obj)
      @data_lock.synchronize { @deserialized_object = obj }
    end

    def get_deserialized_object
      @data_lock.synchronize { @deserialized_object }
    end
  end

  class Serializer
    ALLOWED_CLASSES = %w[String Integer Float Array Hash NilClass TrueClass FalseClass Symbol].freeze

    def initialize(audit_log:)
      @audit_log = audit_log
      @contexts = {}
      @contexts_lock = Mutex.new
    end

    def serialize(object, permissions: [])
      ctx = SerializationContext.new(permissions: permissions)
      register_context(ctx)

      @audit_log.log_operation(:serialize_start, ctx.id, { class: object.class.name })
      ctx.transition_to(:validating)

      validate_object!(object, ctx)
      ctx.transition_to(:serializing)

      data = perform_serialization(object, ctx)
      ctx.set_serialized_data(data)
      ctx.transition_to(:complete)

      @audit_log.log_operation(:serialize_complete, ctx.id)
      data
    end

    def deserialize(data, permissions: [])
      ctx = SerializationContext.new(permissions: permissions)
      register_context(ctx)

      @audit_log.log_operation(:deserialize_start, ctx.id, { size: data.bytesize })
      ctx.transition_to(:validating)

      parsed = safe_parse(data, ctx)
      ctx.transition_to(:checking_permissions)

      check_deserialization_permissions!(parsed, ctx)
      ctx.transition_to(:deserializing)

      result = materialize_object(parsed, ctx)
      ctx.set_deserialized_object(result)
      ctx.transition_to(:complete)

      @audit_log.log_operation(:deserialize_complete, ctx.id)
      result
    end

    private

    def register_context(ctx)
      @contexts_lock.synchronize { @contexts[ctx.id] = ctx }
    end

    def validate_object!(object, ctx)
      unless ALLOWED_CLASSES.include?(object.class.name)
        raise SecurityError, "Cannot serialize #{object.class.name}"
      end
      if object.is_a?(Array) || object.is_a?(Hash)
        validate_nested!(object, ctx)
      end
    end

    def validate_nested!(object, ctx)
      case object
      when Array
        object.each { |item| validate_object!(item, ctx) }
      when Hash
        object.each do |k, v|
          validate_object!(k, ctx)
          validate_object!(v, ctx)
        end
      end
    end

    def perform_serialization(object, ctx)
      envelope = {
        '__safe_serial__' => '1.0',
        'context_id' => ctx.id,
        'payload' => encode_value(object)
      }
      JSON.generate(envelope)
    end

    def encode_value(object)
      case object
      when NilClass, TrueClass, FalseClass, Integer, Float
        { 'type' => object.class.name, 'value' => object }
      when String
        { 'type' => 'String', 'value' => object, 'encoding' => object.encoding.name }
      when Symbol
        { 'type' => 'Symbol', 'value' => object.to_s }
      when Array
        { 'type' => 'Array', 'value' => object.map { |v| encode_value(v) } }
      when Hash
        pairs = object.map { |k, v| [encode_value(k), encode_value(v)] }
        { 'type' => 'Hash', 'value' => pairs }
      end
    end

    def safe_parse(data, ctx)
      parsed = JSON.parse(data)
      unless parsed.is_a?(Hash) && parsed['__safe_serial__'] == '1.0'
        raise SecurityError, "Invalid serialization envelope"
      end
      parsed
    rescue JSON::ParserError => e
      raise SecurityError, "Malformed data: #{e.message}"
    end

    def check_deserialization_permissions!(parsed, ctx)
      payload = parsed['payload']
      required_types = collect_types(payload)
      required_types.each do |type_name|
        unless ALLOWED_CLASSES.include?(type_name)
          @audit_log.log_operation(:permission_denied, ctx.id, { type: type_name })
          raise SecurityError, "Type #{type_name} not permitted"
        end
      end
    end

    def collect_types(node)
      return [] unless node.is_a?(Hash) && node['type']
      types = [node['type']]
      case node['type']
      when 'Array'
        node['value']&.each { |v| types.concat(collect_types(v)) }
      when 'Hash'
        node['value']&.each { |pair| pair.each { |v| types.concat(collect_types(v)) } }
      end
      types
    end

    def materialize_object(parsed, ctx)
      payload = parsed['payload']
      decode_value(payload, ctx)
    end

    def decode_value(node, ctx)
      type_name = node['type']
      value = node['value']

      unless ALLOWED_CLASSES.include?(type_name)
        raise SecurityError, "Type #{type_name} not permitted during materialization"
      end

      case type_name
      when 'NilClass' then nil
      when 'TrueClass' then true
      when 'FalseClass' then false
      when 'Integer' then Integer(value)
      when 'Float' then Float(value)
      when 'String'
        str = String(value)
        encoding = node['encoding']
        unless ['UTF-8', 'ASCII', 'US-ASCII', 'ASCII-8BIT'].include?(encoding)
          encoding = 'UTF-8'
        end
        str.force_encoding(encoding)
        str
      when 'Symbol' then value.to_sym
      when 'Array' then value.map { |v| decode_value(v, ctx) }
      when 'Hash'
        result = {}
        value.each { |pair| result[decode_value(pair[0], ctx)] = decode_value(pair[1], ctx) }
        result
      end
    end
  end
end
